    'global.emails.user_data_collected_appointment_calendar.body' => 'Salut, <strong>{{NAME}}</strong>,<br /><br />Tocmai ai primit o nouă rezervare în <strong>Calendarul de programări</strong>, făcută de unul dintre vizitatorii tăi.<br /><br /><strong>Data:</strong> {{DATA_DATE}}<br /><strong>Ora:</strong> {{DATA_TIME}}<br /><strong>Durată:</strong> {{DATA_DURATION}}<br /><strong>E-mail:</strong> {{DATA_EMAIL}}<br /><strong>Telefon:</strong> {{DATA_PHONE}}<br /><strong>Nume:</strong> {{DATA_NAME}}<br /><strong>Mesaj:</strong> {{DATA_MESSAGE}}<br /><br /><a href="{{DATA_LINK}}" class="cta">Vezi toate datele colectate</a><br /><br />Cu stimă,<br />Echipa {{WEBSITE_TITLE}}.',
