    'global.emails.guest_guest_payment_service.subject' => 'Ai plătit pentru „{{SERVICE_TITLE}}”: {{WEBSITE_TITLE}}',
    'global.emails.guest_guest_payment_service.body' => 'Bună, <strong>{{NAME}}</strong>,<br /><br />Acesta este mesajul oficial prin e-mail care confirmă că ai plasat comanda cu succes. Furnizorul serviciului te va contacta cât mai curând posibil.<br /><br />Cu stimă,<br />Echipa {{WEBSITE_TITLE}}.',
