    'global.emails.auto_delete_inactive_users.subject' => 'Contul tău a fost șters: {{WEBSITE_TITLE}}',
    'global.emails.auto_delete_inactive_users.body' => 'Bună, <strong>{{NAME}}</strong>,<br /><br />Acest e-mail este o simplă notificare prin care te informăm că ți-am șters contul deoarece a fost inactiv mai mult de {{INACTIVITY_DAYS}} de zile.<br /><br />Dacă dorești să recapeți accesul, va trebui să îți creezi un alt cont la noi.<br /><br /><a href="{{REGISTER_LINK}}" class="cta">Înregistrează-te din nou</a><br /><br />Cu stimă,<br />Echipa {{WEBSITE_TITLE}}.',
