    'dashboard.tour.step_sidebar_text' => 'Acesta este meniul principal FCC din contul tău de utilizator. De aici poți accesa tabloul de bord, aplicațiile, planul tău de dezvoltare, rezultatele, materialele educaționale și conținutul despre produse, care te ajută în activitatea ta Forever de zi cu zi.',
    'dashboard.tour.step_menu_apps_title' => 'Aplicații FCC',
    'dashboard.tour.step_menu_apps_text' => 'Aici îți deschizi aplicațiile Forever Card. Acestea sunt baza ta digitală personală, prin care îndrumi vizitatorii către produse, înregistrări, contacte și alte acțiuni importante.',
    'dashboard.tour.step_menu_ai_plan_title' => 'Plan de creștere AI',
    'dashboard.tour.step_menu_ai_plan_text' => 'Aici îți deschizi și urmezi planul de dezvoltare. AI folosește semnalele din aplicațiile tale, conținutul blogului și clicurile din magazinul online pentru a-ți sugera următoarele acțiuni potrivite pentru zilele următoare.',
    'dashboard.tour.step_menu_results_title' => 'Rezultate FCC',
    'dashboard.tour.step_menu_results_text' => 'Aici poți vedea dacă sistemul tău produce cu adevărat rezultate. Această secțiune te ajută să urmărești clicurile, progresul și semnalele care arată ce merită consolidat.',
    'dashboard.tour.step_menu_education_title' => 'Instruire Forever',
    'dashboard.tour.step_menu_education_text' => 'Această secțiune conține materiale video educaționale și explicații care te ajută să înțelegi sistemul, să urmezi pașii și să aplici ceea ce înveți în activitatea de zi cu zi.',
    'dashboard.tour.step_menu_products_title' => 'Produse Forever',
    'dashboard.tour.step_menu_products_text' => 'Aici găsești articole despre produse și conținut cu recomandări. Este unul dintre principalele locuri din care distribui conținutul recomandat de tine și îndrumi persoanele interesate către magazinul online Forever.',
    'dashboard.tour.step_navbar_title' => 'Meniul principal FCC',
    'dashboard.tour.step_navbar_text' => 'Meniul de sus este principala ta cale de navigare către secțiunile de instruire, produse, articole de blog și contact, precum și către tabloul de bord. Aici începe înțelegerea întregului sistem FCC.',
    'dashboard.tour.step_menu_forever_club_title' => 'Forever Card Club',
    'dashboard.tour.step_menu_forever_club_text' => 'Aici găsești informațiile principale despre FCC, explicații despre sistem și conținut care te ajută să înțelegi cum funcționează împreună aplicațiile, recomandările și instrumentele pentru a construi o afacere Forever.',
    'dashboard.tour.step_menu_forever_products_title' => 'Produse Forever',
    'dashboard.tour.step_menu_forever_products_text' => 'Aici găsești conținut despre produse și articole pe care le poți distribui împreună cu recomandarea ta. Este o parte importantă a procesului de a stârni interesul și de a îndruma vizitatorii către magazinul online Forever.',
    'dashboard.tour.step_menu_blog_title' => 'Blog',
    'dashboard.tour.step_menu_blog_text' => 'Blogul îți oferă mai mult conținut educațional și despre afaceri, pe care îl poți folosi în postări și mesaje și pentru a câștiga încredere prin conținut util, nu doar prin vânzare directă.',
    'dashboard.tour.step_menu_contact_title' => 'Contact',
    'dashboard.tour.step_menu_contact_text' => 'Aici poți contacta pe cineva și primi sprijin pentru întrebări suplimentare. Când ceva nu este clar sau ai nevoie de îndrumare, acesta este unul dintre locurile în care poți cere ajutor.',
    'dashboard.tour.step_menu_dashboard_title' => 'Mergi la tabloul de bord',
    'dashboard.tour.step_menu_dashboard_text' => 'Tabloul de bord este centrul tău de comandă. Aici îți urmărești indicatorii, înveți din ghiduri, vezi ce funcționează și decizi care ar trebui să fie următorul pas.',
    'dashboard.tour.step_hero_title' => 'Pagina principală a activității tale FCC',
    'dashboard.tour.step_hero_text' => 'Această secțiune de sus rezumă unde te afli acum, care este obiectivul tău și care sunt cele mai rapide puncte de acces la aplicații, asistență și ghiduri educaționale.',
    'dashboard.tour.step_growth_title' => 'Semnale și deblocări',
    'dashboard.tour.step_growth_text' => 'Aici poți vedea câtă activitate reală direcționează oamenii către magazinul online Forever Living prin aplicația FCC, blogul și celelalte instrumente. Acest indicator influențează ritmul ajutorului oferit de inteligența artificială și deblocările următoare din planul tău de dezvoltare.',
    'dashboard.tour.step_tutorials_title' => 'Tutoriale scurte și materiale educaționale',
    'dashboard.tour.step_tutorials_text' => 'Aici găsești ghiduri practice și scurte pentru acțiuni specifice. Așa funcționează educația FCC în practică, nu doar prin teorie, ci și prin pași mici pe care îi poți pune imediat în aplicare.',
    'dashboard.tour.step_workbench_title' => 'Spațiu de lucru',
    'dashboard.tour.step_workbench_text' => 'Aici vezi imediat ce funcționează, unde se pierd rezultatele și ce părți ale sistemului stârnesc deja interes. Astfel, poți lua decizii pe baza unor semnale reale, nu a presupunerilor.',
    'dashboard.tour.step_chart_title' => 'Clicuri care aduc rezultate',
    'dashboard.tour.step_chart_text' => 'Graficul separă aplicația → Forever, blogul → Forever, înregistrările și contactele de pe pâlnia de vânzări și chatul AI, astfel încât să poți vedea clar care parte a sistemului generează semnale reale pentru afacere.',
    'dashboard.tour.step_next_action_title' => 'Următoarea ta mișcare',
    'dashboard.tour.step_next_action_text' => 'Acest bloc îți oferă o recomandare clară despre ce să faci acum. Scopul FCC nu este să te copleșească cu date, ci să te ajute să alegi următorul pas cel mai util.',
    'dashboard.tour.step_support_title' => 'Subiecte de asistență și webinare',
    'dashboard.tour.step_support_text' => 'Aici poți deschide solicitări de asistență, citi răspunsurile administratorilor și propune subiecte pentru webinare. Acest aspect face parte din instruirea FCC și te ajută când întâmpini dificultăți sau vrei să înțelegi mai bine ceva.',
