    'fcc_results.homepage_spotlight_title' => 'Aplicații recomandate și sponsori sugerați',
    'fcc_results.homepage_spotlight_notice_before' => 'Pe',
    'fcc_results.homepage_spotlight_notice_after' => 'Pe pagină vezi principalele aplicații publice care au cel puțin 15 în 30 de zile. Când un colaborator ajunge la cel puțin 50 în 30 de zile, este inclus în cercul mai vizibil de sponsori recomandați pe pagina principală, cu condiția ca afișarea publică să fie activată și aprobată de administrator.',
    'fcc_results.proof_note' => 'FCC Results afișează indicatorii de activitate. Featured Apps oferă exemple publice cu cel puțin 15 accesări în 30 de zile, iar cel puțin 50 de accesări în 30 de zile consolidează și mai mult șansele de a apărea printre sponsorii recomandați pe pagina principală.',
    'fcc_results.metrics_note' => 'Pragurile și clasamentele iau în calcul vizitele calificate la Forever prin butoane obișnuite și dedicate și prin bloguri, cu protecție împotriva repetării. Un tag UTM singur nu aduce un punct. Contribuția la calificarea pentru pâlnia VIP este afișată separat, iar contactele prin alte pâlnii și prin chatul AI indică interes.',
    'fcc_results.metrics_info.title' => 'Cum se calculează',
    'fcc_results.metrics_info.position' => 'Poziție: locul tău în listă, în funcție de clicurile calificate din perioada selectată (7 sau 30 de zile).',
    'fcc_results.metrics_info.shop_clicks' => 'Accesări calificate: clicuri unice pe blocurile Forever Living și ale magazinului online din aplicațiile FCC, plus clicuri unice de pe blog către Forever, cu etichetele tale de recomandare și UTM.',
    'fcc_results.metrics_info.total_contacts' => 'Contacte: totalul contactelor din pâlnie și al contactelor din chatul AI în perioada selectată.',
    'fcc_results.metrics_info.ctr' => 'Arată ce proporție dintre vizitatorii aplicației tale FCC apasă cel puțin un buton sau o ofertă importantă.',
    'fcc_results.metrics_info.trend' => 'Tendință: modificarea numărului de clicuri calificate față de perioada anterioară de aceeași durată.',
    'fcc_results.metrics_info.to_qualification' => 'Până la calificare: câte clicuri calificate mai sunt necesare pentru a atinge pragul de 15.',
    'fcc_results.metrics_info.to_next_rank' => 'Până la următorul rang: de câte clicuri calificate ai nevoie pentru a-l depăși pe utilizatorul aflat imediat deasupra ta.',
    'fcc_results.tips.title' => 'Cum să ajungi la nivelul următor',
    'fcc_results.tips.subheader' => 'Fă 1-2 acțiuni mici săptămâna aceasta pentru a-ți spori șansele de a intra în clasament sau de a urca în el.',
    'fcc_results.tips.item_1' => 'Publică aplicația Forever Card App pe rețelele sociale și adaugă un îndemn clar la acțiune.',
    'fcc_results.tips.item_2' => 'Trimite aplicația ta Forever Card clienților existenți, ca să o poată folosi la următoarea comandă.',
    'fcc_results.tips.item_3' => 'Mută secțiunea magazinului online mai sus în aplicație, ca să fie vizibilă imediat.',
    'fcc_results.tips.item_4' => 'Adaugă un text scurt deasupra butonului către magazinul online, de exemplu: Vezi produsele pe care ți le recomand.',
    'fcc_results.tips.item_5' => 'Folosește cardul tău fizic NFC în discuțiile cu cunoscuții pentru a le prezenta produsele recomandate printr-o singură atingere.',
    'fcc_results.tips.item_6' => 'Distribuie un produs de pe blogul tău într-un story folosind linkul de distribuire sau trimite-l direct într-un mesaj persoanelor interesate, pentru a crește numărul de vizite în Forever Shop prin recomandarea ta.',
    'fcc_results.tips.item_7' => 'Activează consilierul AI în aplicație și îndrumă vizitatorii să înceapă o conversație, deoarece contactele colectate de AI sunt incluse și ele în rezultatul tău privind contactele.',
    'fcc_results.challenge.title' => 'Provocare săptămânală',
    'fcc_results.challenge.text' => 'Obține %s clicuri unice calificate în 7 zile și intră pe lista persoanelor calificate.',
    'fcc_results.ai_widget.title' => 'Analizele AI și planul tău de creștere',
    'fcc_results.ai_widget.subheader' => 'Acest widget urmărește întotdeauna semnalul tău din ultimele 30 de zile și arată drumul spre nivelul 15+ / 30d pentru Featured Apps, nivelul 50+ / 30d pentru sponsori recomandați și verificarea ritmului pe 7 zile.',
