    'fcc_results.ai_widget.active_benefits' => 'La 15 deblochezi un ritm AI mai intens în planul tău de creștere: un plan săptămânal activ și evaluări recurente ale aplicației cu ajutorul AI.',
    'fcc_results.ai_widget.vip_benefits' => 'La 50, obții un statut superior pe pagina principală și în secțiunea sponsorilor recomandați. Acesta este un semnal de continuitate și experiență în cadrul FCC.',
    'fcc_results.ai_widget.pro_note' => 'Planul tău de creștere și FCC Results folosesc același indicator de calificare pentru pragurile de 15+ și 50+. Contactele de pe WhatsApp și din conversațiile cu AI oferă context suplimentar despre interes, dar nu adaugă puncte la aceste praguri.',
    'fcc_results.ai_widget.pro_required_note' => 'Pentru a debloca întregul flux AI din planul tău de creștere, ai nevoie de un pachet Pro activ. Aici poți vedea în continuare progresul semnalului tău calificat.',
    'fcc_results.ai_widget.featured_note_7d' => '15+ în 30 de zile te include în lista Featured Apps, iar 50+ în 30 de zile te apropie de lista sponsorilor recomandați pe pagina principală. Această vizualizare pe 7 zile servește doar la verificarea ritmului săptămânal.',
    'fcc_results.ai_widget.featured_note_7d_unlocked' => 'Ai deja 50+ în 30 de zile și te afli în zona recomandată superioară pentru sponsori. Dacă menții și 15+ în 7 zile, confirmi un ritm săptămânal constant.',
    'fcc_results.ai_widget.featured_note_7d_experience' => 'Ai cel puțin 50 în 30 de zile și ai confirmat cel puțin 15 în 7 zile. Acesta este un semnal puternic atât pentru recomandările de sponsori, cât și pentru un ritm săptămânal constant.',
