    'ai_plan.app_review_persist_failed_message' => 'Analiza AI din aplicație a fost generată, dar nu s-a salvat corect. Reîncarcă pagina și încearcă din nou. Dacă se întâmplă din nou, sistemul va scurta automat istoricul AI mai vechi, astfel încât noua analiză să poată fi salvată.',
