    'ai_plan.signal_summary.signal_text_default' => 'Există un anumit interes, dar încă nu este suficient de puternic pentru a genera un rezultat stabil fără un obiectiv mai bine definit.',
    'ai_plan.signal_summary.signal_text_zero' => 'Încă nu există semnale reale din Forever Webshop. Primul obiectiv nu este să complici lucrurile, ci să obții primele clicuri de calitate, care au sens.',
    'ai_plan.signal_summary.signal_text_building' => 'În prezent ai %s clicuri către Forever Webshop în ultimele 30 de zile. Ai nevoie de cel puțin %s pentru ca planul săptămânal să se bazeze pe date reale, nu pe presupuneri.',
    'ai_plan.signal_summary.signal_text_ready' => 'Ai %s accesări ale Forever Webshop în ultimele 30 de zile, ceea ce înseamnă că sistemul poate crea acum planul săptămânal pe baza comportamentului real al vizitatorilor.',
    'ai_plan.signal_summary.action_label' => 'Cea mai utilă acțiune în acest moment',
    'ai_plan.signal_summary.action_text_default' => 'Păstrează lucrurile simple: un mesaj clar, o direcție principală și o aplicație pe care chiar o vei folosi săptămâna aceasta.',
    'ai_plan.signal_summary.action_text_direct' => 'Sursa vizitei este neclară prea des. Săptămâna aceasta, nu-ți dispersa eforturile. Folosește un singur format repetabil și o cale clară către Forever Shop.',
    'ai_plan.signal_summary.action_text_recruitment' => 'Dacă te concentrezi pe afacere, folosește o poveste clară și o singură invitație la o discuție în această săptămână, în loc să trimiți prea multe mesaje și oferte deodată.',
    'ai_plan.signal_summary.action_text_building' => 'Prioritatea este să obții primele accesări de calitate către Forever Webshop printr-o activitate repetabilă, nu să începi mai multe idei deodată.',
    'ai_plan.signal_summary.action_text_funnel_live' => 'Momentan, %s din %s pași de vânzare sunt activi. Săptămâna aceasta, obiectivul ar trebui să fie menținerea unui parcurs clar, astfel încât vizitatorul să nu fie nevoit să aleagă prea multe lucruri deodată.',
    'ai_plan.signal_summary.action_text_sales_ready' => 'Semnalul este suficient de puternic pentru ca săptămâna aceasta să te concentrezi pe transformarea interesului în acțiuni în magazinul online, nu doar pe obținerea mai multor vizite.',
    'ai_plan.signal_summary.action_text_weekly_ready' => 'Semnalul este gata. Acum contează verificarea săptămânală, deoarece planul nu mai pornește de la presupuneri, ci de la comportamentul real al vizitatorilor.',
    'ai_plan.signal_summary.watch_label' => 'La ce să fii atent(ă)',
    'ai_plan.signal_summary.watch_text_default' => 'Nu complica aplicația sau activitățile săptămânale mai mult decât permite situația actuală. Claritatea contează mai mult decât amploarea.',
    'ai_plan.signal_summary.watch_text_mobile' => 'Majoritatea oamenilor îți accesează pagina de pe telefon. Primul ecran, primul mesaj și primul clic trebuie să fie clare imediat, fără prea multă derulare sau prea multe opțiuni.',
    'ai_plan.signal_summary.watch_text_funnel_early' => 'Pașii de vânzare există deja, dar semnalele sunt încă slabe. Nu complica prea devreme traseul dacă încă nu ai clicuri de calitate.',
    'ai_plan.signal_summary.watch_text_country' => 'În prezent, cel mai mare interes vine din această piață: %s. Asigură-te că mesajul, exemplul și oferta sunt clare pentru publicul de acolo.',
    'ai_plan.status_card_title' => 'Starea ta actuală',
    'ai_plan.status_card_text_profile' => 'Completează-ți profilul, astfel încât AI să-ți înțeleagă obiectivul, publicul și modul de lucru.',
    'ai_plan.status_card_text_signal' => 'Profilul există, dar încă se construiește un semnal relevant. Prioritatea este să obții încă %s clicuri de calitate către Forever Webshop, astfel încât planul săptămânal să aibă o bază solidă.',
    'ai_plan.status_card_text_weekly' => 'Semnalul este pregătit. Cel mai valoros pas următor este să completezi verificarea săptămânală, astfel încât sistemul să poată crea un plan săptămânal real, nu o sugestie generală.',
    'ai_plan.status_card_text_plan_pending' => 'Există o verificare săptămânală, dar planul nu este încă salvat. Următorul pas este să deschizi planul actual sau să aștepți o nouă trimitere săptămânală pentru un plan nou.',
