    'index.presentation4.feature5' => 'Conform GDPR, CCPA și PECR',
    'index.presentation5.header' => 'Transformă interesul într-o afacere reală',
    'index.presentation5.subheader' => 'Cu FCC Funnel, colectezi mai ușor datele de contact, revii mai repede către oameni și vezi clar ce îți aduce cele mai multe solicitări, contacte interesate și membri noi ai echipei.',
    'index.presentation5.feature1' => 'Colectare mai ușoară a contactelor interesate',
    'index.presentation5.feature2' => 'Comunicare mai rapidă și urmărire mai simplă',
    'index.presentation5.feature3' => 'Vizibilitate și organizare mai bune ale contactelor potențiale',
    'index.presentation5.feature4' => 'Mai multe oportunități de a-ți dezvolta afacerea și echipa',
    'index.presentation6.header' => 'Asistenți IA pentru recomandări de produse',
    'index.presentation6.subheader' => 'Asistenții AI inteligenți îi ajută pe oameni să găsească rapid produse Forever pentru ei, familiile lor și animalele lor de companie, deschizând totodată pentru tine mai multe conversații și oportunități de vânzare.',
