    'index.domains.header' => 'Domenii personalizate',
    'index.domains.subheader' => 'Conectează-ți propriul domeniu sau folosește unul dintre domeniile predefinite.',
    'index.projects.header' => 'Proiecte',
    'index.projects.subheader' => 'Cel mai simplu mod de a-ți categorisi resursele gestionate.',
    'index.file_links.header' => 'Linkuri către fișiere',
    'index.file_links.subheader' => 'Generează linkuri dinamice, avansate și descărcabile către fișiere.',
    'index.vcard_links.header' => 'Carte de vizită digitală',
    'index.vcard_links.subheader' => 'Creează cărți de vizită digitale dinamice, ale căror descărcări și accesări sunt urmărite.',
    'index.splash_pages.header' => 'Pagini de destinație',
    'index.splash_pages.subheader' => 'Folosește pagini intermediare personalizate, cu cronometre pentru linkurile tale.',
    'index.pixels.header' => 'Analiză avansată și monitorizarea performanței',
    'index.pixels.subheader' => 'Toate linkurile inteligente și aplicația Forever Card se integrează cu principalele platforme de analiză și publicitate.',
    'index.pixels.note' => 'Datele de urmărire le permit partenerilor să înțeleagă ce funcționează: ce conținut stârnește interesul, de unde vin vizitatorii și ce campanii generează rezultate. Sistemul permite integrarea cu principalii furnizori de pixeli și servicii de urmărire.',
    'index.pricing.header' => 'Prețuri simple și transparente.',
    'index.testimonials.one.text' => 'Această platformă a transformat complet modul în care ne gestionăm fluxurile de lucru. Este intuitivă și rapidă și a economisit nenumărate ore echipei noastre în fiecare săptămână.',
    'index.testimonials.one.attribute' => 'Editor, Writer\'s Weekly',
    'index.testimonials.two.text' => 'La început eram sceptic, dar în câteva zile am văzut cât de mult a crescut productivitatea echipei noastre. Echipa de asistență răspunde și ea incredibil de repede.',
    'index.partners.header' => 'De ce folosesc partenerii Forever Card Club',
    'index.partners.subheader' => 'Un sistem digital structurat pentru dezvoltarea profesionistă și globală a afacerii Forever.',
    'index.partners.card1.title' => 'Un singur sistem: totul într-un singur loc',
    'index.partners.card1.text' => 'Aplicație personală, linkuri inteligente, instruire, asistență AI și statistici, toate reunite într-un singur ecosistem digital.',
    'index.partners.card2.title' => 'Rutare globală fără complicații',
    'index.partners.card2.text' => 'Linkurile inteligente detectează automat țara vizitatorului și îl direcționează către magazinul online oficial Forever din regiunea sa.',
    'index.partners.card3.title' => 'Prezență profesională online și offline',
    'index.partners.card3.text' => 'Aplicația personală și cardul NFC îți permit să distribui ușor, fără cunoștințe tehnice.',
    'index.partners.card4.title' => 'Structură clară de creștere',
    'index.partners.card4.text' => 'Un plan structurat de 120 de zile și instruirea pas cu pas îi ajută pe parteneri să construiască un sistem stabil și scalabil.',
    'index.faq.header' => 'Răspunsuri la întrebări frecvente',
    'index.faq.one.question' => 'Cum obțin aplicația Forever Card?',
    'index.faq.one.answer' => 'Primești aplicația Forever Card când devii partener de afaceri Forever înregistrat, iar sponsorul tău face parte din echipa noastră. După ce primești acces, urmezi un proces simplu de integrare care îți arată cum să activezi și să configurezi aplicația personală. Aplicația este baza ta digitală: alegi ce secțiuni să afișezi, de exemplu video, produse, consilier AI, contact, educație, și poți configura totul fără cunoștințe tehnice. Dacă lucrezi și offline, primești gratuit un card NFC livrat la adresa ta, care deschide aplicația printr-o atingere sau scanare rapidă.',
    'index.faq.two.question' => 'Cum funcționează comenzile fără înregistrare și recomandările?',
    'index.faq.two.answer' => 'Forever Card Club folosește linkuri inteligente de recomandare, concepute pentru distribuire la nivel global. Când un vizitator accesează linkul tău sau selectează un produs în aplicația ta și alege „comandă”, sistemul poate detecta automat țara vizitatorului și îl poate direcționa către magazinul online oficial Forever din țara sa. Recomandarea ta este inclusă în link, astfel încât achiziția să poată fi asociată cu tine, în calitate de partener care a făcut recomandarea, conform regulilor sistemului oficial. Important: Forever Card Club nu vinde produse. Toate achizițiile se efectuează prin magazinul online oficial din țara clientului.',
    'index.faq.three.question' => 'Ce primesc în calitate de membru al echipei?',
    'index.faq.three.answer' => 'În calitate de membru al echipei, primești un sistem complet pentru dezvoltarea online a unei afaceri Forever, care include: o aplicație Forever Card personală (toate instrumentele și conținutul tău într-un singur loc), linkuri inteligente de recomandare care redirecționează utilizatorii din întreaga lume către magazinul web oficial, un consilier AI care oferă îndrumări despre produse și informații în aplicație, instruire pas cu pas (cum să folosești sistemul și să-ți dezvolți afacerea online), un plan personalizat de 120 de zile, adaptat obiceiurilor și obiectivelor tale, analize (ce accesează oamenii, de unde provin și ce funcționează cel mai bine), precum și un card NFC gratuit, livrat la adresa ta, pentru contactele în persoană. Primești și sprijinul comunității, de exemplu prin grupuri WhatsApp și îndrumări clare, care te ajută să fii consecvent și să obții rezultate pe termen lung.',
    'index.faq.four.question' => 'Cum funcționează planul de 120 de zile?',
    'index.faq.four.answer' => 'Planul de 120 de zile este un program structurat care îi ghidează pe parteneri de la configurarea inițială, prin formarea unor obiceiuri, până la o rutină consecventă de comunicare online, recomandări și dezvoltarea echipei și a bazei de clienți. Nu este un PDF generic. Este conceput să se adapteze fiecărei persoane: la timpul disponibil, stilul de comunicare, nivelul de experiență și obiectivele sale. Planul oferă pași clari despre ce să configurezi în aplicație, cum să folosești linkuri inteligente, cum să prezinți informații online și cum să construiești un sistem repetabil, care poate fi reprodus de viitoarea ta echipă.',
    'index.faq.five.question' => 'Ce face consilierul AI în aplicație?',
    'index.faq.five.answer' => 'Consultantul AI îi ajută pe vizitatori să găsească mai ușor informațiile. Pe baza întrebărilor lor, poate sugera informații și produse relevante, apoi îi poate îndruma către pasul următor, fie că este vorba despre a afla mai multe, a lua legătura sau a plasa o comandă. Dacă vizitatorul alege să comande, consultantul AI îl poate direcționa către magazinul online oficial prin linkuri inteligente, care păstrează asocierea cu partenerul care l-a recomandat. Pentru parteneri, reduce nevoia de a repeta informațiile de bază și contribuie la păstrarea unei comunicări clare și consecvente.',
    'index.faq.contact_note' => 'Dacă dorești acces sau ai o întrebare, contactează-ne prin %s.',
    'index.faq.contact_link' => 'Pagina de contact',
