    'links.short_links.guide_title' => 'Linkuri scurte, explicate acolo unde oamenii chiar au nevoie de ele',
    'links.short_links.guide_text' => 'Creează un link scurt în câteva secunde, apoi folosește opțiunea Editare pentru a-i configura comportamentul. Acum, această vizualizare te ghidează prin crearea linkurilor, gestionarea listei, analiză și setări avansate de redirecționare, astfel încât să poți folosi cu încredere toate opțiunile.',
    'links.short_links.total_label' => 'Linkuri scurte active',
    'links.short_links.guide_card_1_title' => 'Creează rapid',
    'links.short_links.guide_card_1_text' => 'Începe cu un URL de destinație și, opțional, setează un alias personalizat. Dacă îl lași necompletat, sistemul generează unul pentru tine.',
    'links.short_links.guide_card_2_title' => 'Editează cu un scop clar',
    'links.short_links.guide_card_2_text' => 'Deschide Edit pentru a gestiona urmărirea, regulile temporare, conectarea aplicației, protecția prin parolă, mascarea linkurilor, direcționarea către publicul țintă și alte comportamente de redirecționare.',
    'links.short_links.guide_card_3_title' => 'Gestionează la scară largă',
    'links.short_links.guide_card_3_text' => 'Folosește importul în bloc, filtrele, funcțiile de copiere și de generare a codurilor QR, duplicarea, resetarea și comutatoarele de stare pentru a-ți organiza biblioteca mare de linkuri.',
    'links.short_links.guide_card_4_title' => 'Măsoară ce funcționează',
    'links.short_links.guide_card_4_text' => 'Verifică statisticile pentru a vedea care linkuri scurte au cele mai bune rezultate, apoi ajustează setările direct din ecranul de editare.',
