    'links.short_links.empty_text' => 'Începe cu butonul URL prescurtat, apoi deschide Editare pentru a accesa opțiunile de monitorizare, programare, direcționare, protecție și branding.',
    'links.short_links.tour.create_title' => 'Creează un link scurt',
    'links.short_links.tour.create_text' => 'Aceasta este cea mai rapidă modalitate de a adăuga un link scurt nou. Ai nevoie doar de un URL de destinație și, dacă vrei, poți defini și un alias personalizat ușor de reținut.',
    'links.short_links.tour.bulk_title' => 'Importă sau creează în masă',
    'links.short_links.tour.bulk_text' => 'Când ai deja multe destinații pregătite, instrumentele de editare în masă te ajută să creezi mai repede mai multe linkuri scurte și să-ți organizezi mai bine activitățile de lansare.',
    'links.short_links.tour.list_title' => 'Totul rămâne vizibil într-un singur loc',
    'links.short_links.tour.list_text' => 'Această listă devine centrul tău de control pentru linkurile scurte. Numele, previzualizările destinațiilor, statisticile, datele, stările, acțiunile de copiere și comenzile rapide sunt toate ușor de parcurs dintr-o privire.',
    'links.short_links.tour.row_title' => 'Fiecare rând este o redirecționare activă',
    'links.short_links.tour.row_text' => 'Un singur link scurt poate face mult mai mult decât o simplă redirecționare. Din secțiunea de editare, poți adăuga urmărirea UTM, programări, reguli de expirare, mascarea linkului, direcționare și alte funcții avansate.',
    'links.short_links.tour.actions_title' => 'Editează, măsoară, duplică, resetează',
    'links.short_links.tour.actions_text' => 'Folosește meniul de acțiuni pentru a deschide Editare, a vedea statisticile, a crea un cod QR, a duplica, a reseta datele sau a șterge. Tutorialul complet continuă pe ecranul Editare.',
