    'qr_codes.title' => 'Coduri QR',
    'qr_codes.menu' => 'Coduri QR',
    'qr_codes.breadcrumb' => 'Coduri QR',
    'qr_codes.header' => 'Coduri QR',
    'qr_codes.subheader' => 'Creează cu ușurință coduri QR personalizabile și păstrează-le pentru a le folosi mai târziu.',
    'qr_codes.page_intro' => 'Creează coduri QR independente pentru materiale tipărite, distribuire offline, evenimente, produse, Wi-Fi, transmiterea informațiilor de contact și multe alte scenarii. Fiecare aplicație Forever Card poate crea și un cod QR direct propriu, iar această secțiune îți oferă un spațiu de lucru separat pentru a crea și edita coduri QR într-un singur loc.',
    'qr_codes.guide_title' => 'Un spațiu de lucru QR separat pentru materiale tipărite, distribuire offline și scenarii de utilizare controlată',
    'qr_codes.guide_text' => 'Această secțiune QR este destinată elementelor QR independente, pe care vrei să le gestionezi în afara unui anumit ecran al aplicației. Folosește-o când ai nevoie de coduri QR pentru imprimare, coduri de campanie reutilizabile, puncte de acces pentru evenimente sau produse ori de un cod QR cu stil propriu și un proces dedicat de export.',
    'qr_codes.guide_card_1_title' => 'Separat de codul QR al aplicației',
    'qr_codes.guide_card_1_text' => 'Fiecare aplicație Forever Card poate genera propriul cod QR direct, dar aici poți crea coduri QR complet separate pentru alte pagini de destinație, linkuri, materiale și campanii.',
    'qr_codes.guide_card_2_title' => 'Creat pentru tipărire și utilizare offline',
    'qr_codes.guide_card_2_text' => 'Aceste coduri QR sunt ideale pentru pliante, cărți de vizită, afișe, fișe de produs, mese la evenimente, ambalaje și distribuire directă, când oamenii pot scana codul în loc să tasteze.',
    'qr_codes.guide_card_3_title' => 'Personalizează și exportă corect',
    'qr_codes.guide_card_3_text' => 'Controlează tipul și stilul codului QR, culorile, chenarele, sigla, brandingul și formatul fișierului, astfel încât codul final să se potrivească contextului în care va fi folosit.',
    'qr_codes.guide_card_4_title' => 'Editează și refolosește mai târziu',
    'qr_codes.guide_card_4_text' => 'După ce este creat, fiecare cod QR rămâne disponibil pentru descărcare, imprimare, duplicare și modificări ulterioare, fără să fie nevoie să-l creezi din nou de la zero.',
    'qr_codes.empty_title' => 'Creează primul tău cod QR',
    'qr_codes.empty_text' => 'Începe cu un cod QR independent pentru un link, o aplicație, un contact, un eveniment sau un material tipărit. După creare, poți reveni pentru a edita stilul, rama, brandingul și formatul de export.',
    'qr_codes.tour.create_title' => 'Creează un cod QR autonom',
    'qr_codes.tour.create_text' => 'Folosește acest buton când vrei un cod QR care să poată fi accesat și în afara unei singure pagini din Forever Card App. Este ideal pentru campanii, materiale tipărite, evenimente și distribuire offline reutilizabilă.',
    'qr_codes.tour.guide_title' => 'Înțelege când această secțiune este locul potrivit',
    'qr_codes.tour.guide_text' => 'Acest ghid explică diferența dintre codurile QR specifice aplicației și elementele QR independente. Scopul este să-i ajute pe utilizatori să aleagă fluxul potrivit înainte de a crea sau edita.',
    'qr_codes.tour.list_title' => 'Biblioteca ta de coduri QR rămâne organizată aici',
    'qr_codes.tour.list_text' => 'Această listă devine centrul de control pentru fiecare cod QR independent. Previzualizarea, numele, tipul, proiectul asociat, opțiunile de export și accesul pentru editare sunt toate la un loc.',
    'qr_codes.tour.row_title' => 'Fiecare rând este o resursă QR reutilizabilă',
    'qr_codes.tour.row_text' => 'Un cod QR poate reprezenta aici o adresă URL, un link către o aplicație, un eveniment, o conexiune Wi-Fi, un vCard, o solicitare de plată sau multe alte experiențe accesate prin scanare. Poți continua să îmbunătățești același element în timp.',
    'qr_codes.tour.actions_title' => 'Descarcă, imprimă, editează, duplică',
    'qr_codes.tour.actions_text' => 'Folosește acțiunile din dreapta pentru a exporta în diferite formate, a deschide Edit, a duplica un cod QR funcțional pentru o campanie nouă sau a elimina materialele vechi de care nu mai ai nevoie.',
