    'qr_code_update.header' => 'Editează codul QR',
    'qr_codes.editor.hero_title' => 'Transformă un cod QR simplu într-un punct de acces reutilizabil, de la offline la digital',
    'qr_codes.editor.hero_text' => 'Acest editor transformă un cod QR într-un instrument practic, personalizat cu brandul tău și pregătit pentru utilizare reală. Fiecare aplicație Forever Card poate genera propriul cod QR, dar aici poți crea și îmbunătăți separat coduri QR pentru materiale tipărite, campanii, evenimente, parcursuri de produs, distribuirea contactelor și multe alte situații în care cineva scanează un cod.',
    'qr_codes.editor.hero_card_1_title' => 'Alege rezultatul scanării',
    'qr_codes.editor.hero_card_1_text' => 'Decide dacă prin codul QR se va deschide un URL, un card de contact, un flux de plată, o conexiune WiFi, o ciornă de mesaj, un eveniment, o locație sau o altă acțiune acceptată.',
    'qr_codes.editor.hero_card_2_title' => 'Adaptează-l contextului',
    'qr_codes.editor.hero_card_2_text' => 'Ajustează stilul, culorile, cadrul, brandingul și logo-ul opțional, astfel încât codul QR să se potrivească unui pliant, unei cărți de vizită, unei fișe de produs, unei prezentări sau materialelor pentru un eveniment.',
    'qr_codes.editor.hero_card_3_title' => 'Previzualizează înainte de imprimare',
    'qr_codes.editor.hero_card_3_text' => 'Folosește previzualizarea live, verificarea lizibilității și opțiunile de descărcare pentru a testa materialul înainte ca QR-ul să fie imprimat sau distribuit public.',
    'qr_codes.editor.hero_card_4_title' => 'Refolosește în loc să o iei de la capăt',
    'qr_codes.editor.hero_card_4_text' => 'După ce un cod QR funcționează bine, continuă să-l editezi, să-l duplici sau să-l exporți pentru campanii noi, în loc să o iei de la capăt de fiecare dată.',
    'qr_codes.editor.tour.intro_title' => 'Prezentare generală a editorului QR',
    'qr_codes.editor.tour.intro_text' => 'Această pagină te ajută să creezi sau să ajustezi un cod QR independent, care poate fi tipărit, distribuit, exportat și reutilizat în multe contexte.',
    'qr_codes.editor.tour.type_title' => 'Alege ce ar trebui să facă scanarea',
    'qr_codes.editor.tour.type_text' => 'Tipul de cod QR stabilește ce se întâmplă când este scanat: se deschide un link, se salvează datele de contact, se compune un mesaj, se conectează la WiFi, se afișează o solicitare de plată și multe altele.',
    'qr_codes.editor.tour.basics_title' => 'Începe cu numele și datele principale',
    'qr_codes.editor.tour.basics_text' => 'Alege un nume intern clar pentru codul QR și completează câmpurile esențiale. Acesta este conținutul de bază care va fi încorporat în cod.',
    'qr_codes.editor.tour.style_title' => 'Personalizează chiar modelul QR',
    'qr_codes.editor.tour.style_text' => 'Stilul controlează geometria modulelor și a elementelor de colț ale codului QR. Este util când codul QR trebuie să se potrivească vizual cu un brand, o campanie sau un material tipărit.',
    'qr_codes.editor.tour.colors_title' => 'Controlează contrastul și claritatea la scanare',
    'qr_codes.editor.tour.colors_text' => 'Culorile nu sunt doar un element estetic. Un contrast bun este esențial pentru scanarea fiabilă, mai ales dacă codul QR va fi tipărit sau privit în condiții de iluminare necorespunzătoare.',
    'qr_codes.editor.tour.frame_title' => 'Adaugă context în jurul codului QR',
    'qr_codes.editor.tour.frame_text' => 'Ramele ajută codul QR să pară mai bine gândit și pot include un îndemn la acțiune sau o etichetă, astfel încât oamenii să înțeleagă imediat de ce ar trebui să îl scaneze.',
    'qr_codes.editor.tour.branding_title' => 'Adaugă cu grijă sigla și elementele de brand',
    'qr_codes.editor.tour.branding_text' => 'Opțiunile de branding îți permit să adaugi logo-uri și imagini în codul QR, dar trebuie să le testezi cu atenție pentru a păstra lizibilitatea.',
    'qr_codes.editor.tour.options_title' => 'Finalizează setările tehnice',
    'qr_codes.editor.tour.options_text' => 'Dimensiunea, marginea, codificarea, corecția erorilor și organizarea proiectului ajută codul QR să funcționeze corect la export și în producție.',
    'qr_codes.editor.tour.preview_title' => 'Urmărește codul QR final în timp real',
    'qr_codes.editor.tour.preview_text' => 'În previzualizare confirmi că QR-ul arată clar și poate fi scanat înainte de a-l descărca, imprima sau distribui.',
    'qr_codes.editor.tour.download_title' => 'Pregătește materialul pentru tipărire sau livrare',
    'qr_codes.editor.tour.download_text' => 'Exportă în format SVG, PNG, JPG sau WEBP, în funcție de nevoile tale: calitate pentru tipărire, transparență, prezentare sau distribuire rapidă.',
    'qr_codes.editor.tour.save_title' => 'Salvează, testează, apoi publică',
    'qr_codes.editor.tour.save_text' => 'După salvare, scanează codul QR cu cel puțin un telefon înainte să îl folosești public. Acest lucru este deosebit de important dacă sunt implicate rame, degradeuri, sigle sau materiale tipărite.',
    'biolink_block_delete.header' => 'Șterge blocul',
    'biolink_block_delete.subheader' => 'Toate datele asociate blocului FCC vor fi șterse complet. Această acțiune nu poate fi anulată.',
    'biolink_block_delete.success_message' => 'Blocul FCC a fost șters cu succes.',
    'biolink_block.title' => 'Bloc FCC',
    'links_statistics.title' => 'Statistici despre linkuri',
    'links_statistics.menu' => 'Statistici despre linkuri',
    'links_statistics.breadcrumb' => 'Statistici despre linkuri',
    'links_statistics.header' => 'Statistici despre linkuri',
    'link.header.subheader' => 'Aplicația Forever Card: %s',
    'link.header.short_link_subheader' => 'Setări pentru link scurt: %s',
    'link.short_editor.hero_title' => 'Transformă un URL scurt și simplu într-un flux de redirecționare controlat',
    'link.short_editor.hero_text' => 'Acest editor transformă un link scurt într-un instrument strategic. Pe lângă alias și destinație, poți adăuga programare, urmărire UTM, protecție prin parolă, conectarea la aplicații, mascarea linkului, direcționare în funcție de dispozitiv sau locație, comportament HTTP și alte opțiuni avansate.',
    'link.short_editor.hero_card_1_title' => 'Începe cu lucrurile de bază',
    'link.short_editor.hero_card_1_text' => 'Definește URL-ul de destinație, alege un alias scurt și stabilește domeniul pe care vrei să îl folosești pentru linkul scurt.',
    'link.short_editor.hero_card_2_title' => 'Decide cum funcționează',
    'link.short_editor.hero_card_2_text' => 'Controlează când funcționează linkul, unde redirecționează, ce se întâmplă după expirare și dacă trebuie să transmită mai departe parametrii de interogare.',
    'link.short_editor.hero_card_3_title' => 'Urmărește și personalizează',
    'link.short_editor.hero_card_3_text' => 'Adaugă etichete UTM, pixeli, metadate de camuflare și conectare la aplicație, astfel încât fiecare clic să includă contextul de care ai nevoie.',
    'link.short_editor.hero_card_4_title' => 'Protejează și optimizează',
    'link.short_editor.hero_card_4_text' => 'Folosește parole, avertismente privind conținutul sensibil, direcționarea către public și coduri de redirecționare pentru a adapta fiecare campanie la publicul vizat.',
    'link.short_editor.form_title' => 'Ce poți configura pentru un link scurt',
    'link.short_editor.form_text' => 'Deschide doar secțiunile de care ai nevoie sau urmează tutorialul pas cu pas. Fiecare grup de mai jos controlează un nivel al experienței cu linkurile scurte, de la redirecționări simple la logica avansată a campaniilor.',
    'link.short_editor.card_1_title' => 'Pentru lansări fără probleme',
    'link.short_editor.card_1_text' => 'Setează destinația, aliasul, domeniul și codul de redirecționare astfel încât linkul să funcționeze exact cum dorești încă de la prima distribuire.',
    'link.short_editor.card_2_title' => 'Pentru campanii și raportare',
    'link.short_editor.card_2_text' => 'Adaugă valori UTM, pixeli, rapoarte și proiecte pentru ca traficul să poată fi măsurat și grupat corect.',
    'link.short_editor.card_3_title' => 'Pentru comportamentul avansat',
    'link.short_editor.card_3_text' => 'Programează disponibilitatea, stabilește reguli de expirare, protejează accesul, alege publicul țintă sau ascunde pagina de destinație atunci când este nevoie.',
    'link.short_editor.tour.intro_title' => 'Prezentare generală a editorului de linkuri scurte',
    'link.short_editor.tour.intro_text' => 'Această pagină reunește toate opțiunile avansate pentru un singur link scurt. Scopul este simplu: să-i ajute pe oameni să înțeleagă ce modifică fiecare setare înainte de a salva.',
    'link.short_editor.tour.basics_title' => 'Începe cu lucrurile de bază',
    'link.short_editor.tour.basics_text' => 'Aici definești destinația către care duce linkul scurt, aliasul pe care îl folosește și domeniul pe care va fi găzduit. Acestea sunt setările principale de redirecționare.',
    'link.short_editor.tour.app_linking_title' => 'Deschide direct aplicațiile mobile',
    'link.short_editor.tour.app_linking_text' => 'Asocierea aplicațiilor permite deschiderea destinațiilor mobile compatibile în aplicația nativă, nu doar în browser, ceea ce poate îmbunătăți experiența utilizatorilor pe telefoane.',
    'link.short_editor.tour.temporary_title' => 'Setează regulile de programare și expirare',
    'link.short_editor.tour.temporary_text' => 'Folosește această secțiune pentru a programa disponibilitatea, a limita numărul de clicuri sau a stabili unde ajung oamenii după expirarea linkului. Este ideală pentru promoții, lansări și campanii cu durată limitată.',
    'link.short_editor.tour.utm_title' => 'Adaugă context analitic',
    'link.short_editor.tour.utm_text' => 'Parametrii UTM ajută instrumentele de analiză să identifice sursa traficului, mediul și campania. Acesta este unul dintre cele mai utile locuri pentru a standardiza denumirile campaniilor.',
    'link.short_editor.tour.protection_title' => 'Protejează accesul atunci când este necesar',
    'link.short_editor.tour.protection_text' => 'Avertismentele privind parolele și conținutul sensibil sunt utile atunci când un link nu ar trebui să fie complet deschis sau când vizitatorii au nevoie de context înainte de a continua.',
    'link.short_editor.tour.targeting_title' => 'Direcționează categorii diferite de public către destinații diferite',
    'link.short_editor.tour.targeting_text' => 'Direcționarea permite unui singur link scurt să se adapteze în funcție de țară, oraș, dispozitiv, sistem de operare, limba browserului sau reguli de rotație. Este o funcție puternică pentru campanii segmentate.',
    'link.short_editor.tour.cloaking_title' => 'Controlează previzualizarea pe care o văd oamenii',
    'link.short_editor.tour.cloaking_text' => 'Cloaking-ul schimbă titlul, descrierea, imaginea și alte metadate afișate înainte de redirecționare. Este util când previzualizarea distribuită trebuie să corespundă mesajului campaniei.',
    'link.short_editor.tour.http_title' => 'Alege tipul de redirecționare',
    'link.short_editor.tour.http_text' => '301, 302, 307 și 308 nu sunt identice. Această secțiune stabilește dacă redirecționarea este considerată permanentă sau temporară și cum trebuie să o trateze browserele.',
    'link.short_editor.tour.advanced_title' => 'Încheie cu setările avansate',
    'link.short_editor.tour.advanced_text' => 'Aici găsești proiecte, pagini de prezentare, notificări, redirecționarea interogărilor și opțiuni similare, astfel încât linkul scurt să se integreze într-un flux de lucru mai amplu.',
    'link.short_editor.tour.save_title' => 'Salvează și testează',
    'link.short_editor.tour.save_text' => 'După salvare, testează linkul scurt pe desktop și mobil, apoi verifică statisticile pentru a confirma că redirecționările, atribuirea și direcționarea funcționează conform așteptărilor.',
