    'global.emails.admin.fcc_access_rejected_not_team.subject' => 'Accesul FCC nu a fost aprobat, dar Force Click este disponibil / Accesul FCC nu a fost aprobat, dar Force Click este disponibil.',
    'global.emails.admin.fcc_access_rejected_not_team.body' => 'Bună, {{NAME}}, <br /><br />

îți mulțumim că te-ai înregistrat la <strong>Forever Card Club</strong>. După o verificare manuală, momentan nu îți putem aproba accesul la FCC, deoarece Forever Card Club este o platformă privată destinată membrilor structurii Forever a managerilor Diamond Sapphire <strong>Snježana și Stjepan Beloša</strong>. <br /><br />

Contul tău Forever Card Club a fost eliminat din sistem. <br /><br />

Dacă vrei să folosești instrumente online similare pentru afacerea ta Forever, îți recomandăm <strong>Force Click</strong>, platforma noastră soră, disponibilă unui grup mai larg de asociați Forever. <br /><br />

<div style="padding:18px 20px;border-radius:16px;background:linear-gradient(135deg,#0f2440 0%,#153a4d 100%);border:1px solid rgba(83,214,206,0.28);margin:18px 0;">
    <div style="font-size:12px;letter-spacing:0.12em;text-transform:uppercase;color:#9de7e0;margin-bottom:8px;">Force Click for Forever / Force Click za Forever</div>
    <div style="color:#ffffff;line-height:1.75;">
        Prezentări de produse online, linkuri de vânzare, promovare QR/NFC, conținut și o prezență digitală mai ușor de gestionat. <br />
