Cu stimă, <br />
{{WEBSITE_TITLE}}

<hr style="border:none;border-top:1px solid rgba(255,255,255,0.14);margin:24px 0;" />

Stimate/Stimată {{NAME}}, <br /><br />

îți mulțumim pentru înregistrarea la <strong>Forever Card Club</strong>. În urma unei verificări manuale, momentan nu îți putem aproba accesul la FCC, deoarece Forever Card Club este o platformă privată destinată membrilor structurii Forever a managerilor Diamond Saphir <strong>Snježana și Stjepan Beloša</strong>. <br /><br />

Contul tău Forever Card Club a fost eliminat din sistem. <br /><br />

Dacă vrei să folosești instrumente online similare pentru afacerea ta Forever, îți recomandăm <strong>Force Click</strong>, platforma noastră soră, deschisă unui grup mai larg de asociați Forever. <br /><br />

Poți accesa aici pagina Force Click pentru Forever Living Products: {{FORCE_CLICK_LINK}} <br /><br />

Dacă consideri că accesul la FCC ți-a fost refuzat din greșeală, poți trimite o solicitare sau o plângere la {{CONTACT_EMAIL}}. <br /><br />

Îți mulțumim pentru înțelegere. <br /><br />

Cu stimă, <br />
