    'fcc_ai.platform.title' => 'Prezentarea platformei',
    'fcc_ai.platform.note_admin' => 'Detaliile tehnice rămân disponibile mai jos, în secțiuni extensibile, iar ecranul principal rămâne aerisit.',
    'fcc_ai.platform.note_user' => 'Vezi într-un singur loc cum este activată AI în aplicație, cum funcționează Coach și unde sunt urmărite conversațiile și lead-urile.',
    'fcc_ai.platform.list.app_blocks_title' => 'Blocuri AI în aplicație',
    'fcc_ai.platform.list.app_blocks_text' => 'AI-ul public este activat prin adăugarea unui bloc AI în setările aplicației FCC. După ce îl adaugi, AI-ul apare în acea aplicație.',
    'fcc_ai.platform.list.coach_title' => 'FCC Coach',
    'fcc_ai.platform.list.coach_text' => 'Coach este mereu disponibil în FCC, conectat la planul de dezvoltare și conceput pentru a susține platforma, rețelele sociale, comunicarea și dezvoltarea afacerii.',
    'fcc_ai.platform.list.single_ai_title' => 'Un AI pentru fiecare aplicație',
    'fcc_ai.platform.list.single_ai_text' => 'Într-o singură aplicație FCC poate fi activ un singur consilier AI. Dacă ai adăugat deja un bloc AI, adăugarea altuia va afișa un avertisment.',
    'fcc_ai.platform.list.leads_title' => 'Clienți potențiali AI',
    'fcc_ai.platform.list.leads_text' => 'Contactele potențiale generate de AI sunt salvate în dosarul existent /data și asociate conversației relevante.',
    'fcc_ai.guide.title' => 'Cum să folosești FCC AI',
    'fcc_ai.guide.subtitle' => 'Aceste ghiduri scurte explică ce poate face fiecare AI și cum să profiți cât mai mult de el în activitatea de zi cu zi.',
    'fcc_ai.guide.coach.title' => 'AI Coach',
    'fcc_ai.guide.coach.summary' => 'Sprijin pentru activitatea FCC, planul tău de creștere și următorii pași practici.',
    'fcc_ai.guide.coach.intro' => 'FCC Coach este asistentul tău personal în platformă. Este conectat la planul tău de creștere și te ajută să identifici următorul pas cel mai util.',
    'fcc_ai.guide.coach.point_1' => 'Te poate ajuta cu planificarea, stabilirea priorităților, concentrarea și următorul pas atunci când te simți blocat sau nu știi ce să faci mai departe.',
    'fcc_ai.guide.coach.point_2' => 'Oferă idei de conținut, comunicare, rețele sociale și acțiuni zilnice care susțin dezvoltarea afacerii.',
    'fcc_ai.guide.coach.point_3' => 'Te îndrumă prin Planul tău de creștere și îți oferă sfaturi adaptate nevoilor tale actuale.',
    'fcc_ai.guide.coach.tip' => 'Obții cel mai mult beneficiu când explici clar în ce situație te afli, ce vrei să obții și de ce fel de ajutor ai nevoie acum.',
    'fcc_ai.guide.sales.title' => 'AI pentru vânzări, recomandări și colaborare în afaceri',
    'fcc_ai.guide.sales.summary' => 'AI public care recomandă produse, folosește blogul și identifică interesul pentru colaborare.',
    'fcc_ai.guide.sales.intro' => 'Acest AI discută cu vizitatorii aplicației tale FCC, îi ajută să găsească produse pentru oameni sau animale de companie și îi îndrumă către pasul următor, o achiziție sau o colaborare de afaceri.',
    'fcc_ai.guide.sales.point_1' => 'Răspunde la întrebări, recomandă produse și poate îndruma vizitatorul către articolul potrivit de pe blogul FCC pentru explicații mai detaliate.',
    'fcc_ai.guide.sales.point_2' => 'Îl însoțește pe vizitator pe tot parcursul fluxului, de la prima întrebare până la continuarea conversației pe blog sau până la luarea legăturii.',
    'fcc_ai.guide.sales.point_3' => 'Poate colecta date de la vizitatorii interesați și poate salva un potențial client, pentru ca partenerul să poată reveni cu un mesaj.',
    'fcc_ai.guide.sales.point_4' => 'Poate identifica interesul pentru afacere și poate sprijini sponsorizarea, îndrumând vizitatorul către următorul pas relevant.',
    'fcc_ai.guide.sales.tip' => 'Funcționează cel mai bine când tonul este clar, regulile sunt ferme, iar logica recomandărilor este explicată bine.',
    'fcc_ai.guide.settings.title' => 'Setările consultantului',
    'fcc_ai.guide.settings.summary' => 'Aici stabilești cum vorbește AI-ul public, cum răspunde și ce evidențiază.',
    'fcc_ai.guide.settings.intro' => 'În setările publice ale consilierului AI, poți ajusta comunicarea astfel încât să se potrivească stilului tău, publicului și obiectivului aplicației.',
    'fcc_ai.guide.settings.point_1' => 'Numele și limba asistentului stabilesc cum se prezintă AI-ul și ce limbă folosește în mod firesc.',
    'fcc_ai.guide.settings.point_2' => 'Tonul ajută AI-ul să comunice într-un mod consultativ, încurajator, prietenos sau mai direct, în funcție de ce îți dorești.',
    'fcc_ai.guide.settings.point_3' => 'În instrucțiunile pentru persona, descrie stilul dorit: o abordare mai caldă, răspunsuri mai scurte, mai multe întrebări, un accent mai puternic pe produse sau unul mai puternic pe afaceri.',
    'fcc_ai.guide.settings.point_4' => 'În secțiunea cu reguli și limite, definește ce trebuie să menționeze întotdeauna AI-ul, ce trebuie să evite și cum trebuie formulate recomandările.',
    'fcc_ai.guide.settings.tip' => 'De obicei, instrucțiunile scurte și concrete funcționează cel mai bine. Scrie-le ca și cum ai explica cum ar trebui să discute cu un vizitator un consilier bun.',
    'fcc_ai.guide.inbox.title' => 'Mesaje primite de AI în ultimele 30 de zile',
    'fcc_ai.guide.inbox.summary' => 'Locul în care urmărești conversațiile și potențialii clienți și îmbunătățești comunicarea prin chat cu AI.',
    'fcc_ai.guide.inbox.intro' => 'Mesajele primite de AI arată cum a comunicat asistentul cu utilizatorii reali. Acesta este cel mai bun loc pentru a monitoriza calitatea și a îmbunătăți constant asistentul.',
    'fcc_ai.guide.inbox.point_1' => 'Deschide conversațiile și analizează unde a răspuns bine AI-ul și unde răspunsul ar putea fi mai clar sau mai util.',
    'fcc_ai.guide.inbox.point_2' => 'Urmărește ce întrebări se repetă des, ca să poți îmbunătăți tonul, instrucțiunile pentru persona și regulile.',
    'fcc_ai.guide.inbox.point_3' => 'Dacă utilizatorii cer în continuare mai multe explicații, scurtează răspunsurile, adaugă pași mai clari sau îndrumă-i mai bine către blog ori pagina de contact.',
    'fcc_ai.guide.inbox.point_4' => 'Urmărește clienții potențiali atrași de AI și folosește aceste informații pentru a înțelege unde contribuie cel mai mult conversația la vânzări și sponsorizare.',
    'fcc_ai.guide.inbox.tip' => 'Dacă observi aceeași problemă de mai multe ori, ajustează imediat setările consilierului. Schimbările mici de ton și de reguli pot aduce o îmbunătățire semnificativă.',
